              background: 'transparent',
              fontWeight: activeResultTab === 'charts' ? 'bold' : '600',
              color: activeResultTab === 'charts' ? '#1f6b3b' : '#666',
              cursor: 'pointer',
              fontSize: '0.92rem'
            }}
          >
            📊 Error Comparison &amp; Convergence
          </button>
        </div>

        {/* TAB 1: MODEL REGISTRY BENCHMARK TABLE (Crystal Clear High-Contrast Header) */}
        {(activeResultTab === 'overview' || activeResultTab === 'registry') && (
          <div style={{ marginBottom: '24px' }}>
            <div style={{ overflowX: 'auto', borderRadius: '12px', border: '1px solid #d5e5d5' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'center', fontSize: '0.95rem' }}>
                <thead>
                  <tr style={{ background: '#1e3c2f', color: '#ffffff' }}>
                    <th style={{ padding: '16px 14px', textAlign: 'left', color: '#ffffff', fontWeight: '700', fontSize: '0.85rem', letterSpacing: '0.5px' }}>
                      OPTION
                    </th>
                    <th style={{ padding: '16px 14px', color: '#ffffff', fontWeight: '700', fontSize: '0.85rem', letterSpacing: '0.5px' }}>
                      RMSE
                    </th>
                    <th style={{ padding: '16px 14px', color: '#ffffff', fontWeight: '700', fontSize: '0.85rem', letterSpacing: '0.5px' }}>
                      MAPE
                    </th>
                    <th style={{ padding: '16px 14px', color: '#ffffff', fontWeight: '700', fontSize: '0.85rem', letterSpacing: '0.5px' }}>
                      MAE
                    </th>
                    <th style={{ padding: '16px 14px', textAlign: 'right', color: '#ffffff', fontWeight: '700', fontSize: '0.85rem', letterSpacing: '0.5px' }}>
