                        <div style={{ fontSize: '0.78rem', color: '#7f8c8d', marginTop: '2px' }}>
                          {row.subtitle}
                        </div>
                      </td>
                      <td style={{ padding: '16px 14px', fontWeight: 'bold', color: row.isChampion ? '#1e7e40' : '#2c3e50', fontSize: '1rem' }}>
                        ({row.rmse})
                      </td>
                      <td style={{ padding: '16px 14px', fontWeight: 'bold', color: row.isChampion ? '#1e7e40' : '#2c3e50', fontSize: '1rem' }}>
                        ({row.mape})
                      </td>
                      <td style={{ padding: '16px 14px', fontWeight: 'bold', color: row.isChampion ? '#1e7e40' : '#2c3e50', fontSize: '1rem' }}>
                        ({row.mae})
                      </td>
                      <td style={{ padding: '16px 14px', textAlign: 'right' }}>
                        <span style={{
                          padding: '6px 14px',
                          borderRadius: '20px',
                          fontSize: '0.78rem',
                          fontWeight: 'bold',
                          background: row.isChampion ? '#27ae60' : row.isTrained ? '#e8f4fc' : '#f5f5f5',
                          color: row.isChampion ? 'white' : row.isTrained ? '#1976d2' : '#888',
                          boxShadow: row.isChampion ? '0 2px 8px rgba(39, 174, 96, 0.3)' : 'none'
                        }}>
                          {row.badge}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* TAB 2: SARIMA HYPERPARAMETER SEARCH RESULT TABLE (Crystal Clear High-Contrast Header) */}
        {(activeResultTab === 'overview' || activeResultTab === 'sarima') && (
          <div style={{ marginTop: '20px', marginBottom: '24px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '8px', marginBottom: '12px' }}>
              <h4 style={{ margin: 0, fontSize: '1.15rem', color: '#1a3320', display: 'flex', alignItems: 'center', gap: '8px' }}>
                <span>🔍</span> SARIMA Hyperparameter Search: (p, d, q)(P, D, Q)s Result Table
              </h4>
              <span style={{ fontSize: '0.8rem', color: '#556b5b' }}>
                Evaluates parameter combinations across Seasonal and Non-Seasonal loops to find minimum AIC.
              </span>
            </div>

            <div style={{ overflowX: 'auto', borderRadius: '12px', border: '1px solid #d5e5d5' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: '0.9rem' }}>
                <thead>
                  <tr style={{ background: '#1e3c2f', color: '#ffffff' }}>
                    <th style={{ padding: '14px', color: '#ffffff', fontWeight: '700', fontSize: '0.85rem' }}>
                      Candidate Parameter Combination
                    </th>
                    <th style={{ padding: '14px', color: '#ffffff', fontWeight: '700', fontSize: '0.85rem' }}>
                      CV Metric (AIC)
